import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import "../css/homepage.css";

const API_BASE_URL = "http://localhost:5001";
const THAI_MONTHS = [
  "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
  "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
];
const WEEKDAYS = ["อา", "จ", "อ", "พ", "พฤ", "ศ", "ส"];

function getLocalDateString(date) {
  return [
    date.getFullYear(),
    String(date.getMonth() + 1).padStart(2, "0"),
    String(date.getDate()).padStart(2, "0")
  ].join("-");
}

function groupRoomsByFloor(rooms) {
  const grouped = new Map();
  rooms.forEach(room => {
    const floor = Number(room.floor) || 1;
    if (!grouped.has(floor)) grouped.set(floor, []);
    grouped.get(floor).push(room);
  });

  return [...grouped.entries()]
    .sort(([floorA], [floorB]) => floorA - floorB)
    .map(([floor, floorRooms]) => ({ floor, rooms: floorRooms }));
}

function Homepage() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [rooms, setRooms] = useState([]);
  const [roomsError, setRoomsError] = useState("");
  const [search, setSearch] = useState("");
  const [floor, setFloor] = useState("all");
  const [profileOpen, setProfileOpen] = useState(false);
  const [calendarOpen, setCalendarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(() => new Date(2026, 5, 14));
  const [calendarMonth, setCalendarMonth] = useState(() => new Date(2026, 5, 1));
  const [bookingRoom, setBookingRoom] = useState(null);
  const [bookingDate, setBookingDate] = useState(getLocalDateString(new Date()));
  const [bookingStart, setBookingStart] = useState("09:00");
  const [bookingEnd, setBookingEnd] = useState("10:00");
  const [bookingError, setBookingError] = useState("");
  const [savingBooking, setSavingBooking] = useState(false);

  useEffect(() => {
    try {
      const storedUser = JSON.parse(localStorage.getItem("user") || "null");
      if (!storedUser) {
        navigate("/", { replace: true });
        return;
      }
      setUser(storedUser);
    } catch (error) {
      console.error("Invalid stored user data:", error);
      localStorage.removeItem("user");
      localStorage.removeItem("token");
      navigate("/", { replace: true });
    }
  }, [navigate]);

  useEffect(() => {
    if (!user) return undefined;
    const controller = new AbortController();

    fetch(`${API_BASE_URL}/api/rooms`, { signal: controller.signal })
      .then(response => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      })
      .then(data => setRooms(Array.isArray(data.rooms) ? data.rooms : []))
      .catch(error => {
        if (error.name === "AbortError") return;
        console.error("Unable to load rooms:", error);
        setRoomsError("ไม่สามารถโหลดข้อมูลห้องได้ กรุณาตรวจสอบ backend");
      });

    return () => controller.abort();
  }, [user]);

  const filteredSections = useMemo(() => {
    const keyword = search.trim().toLocaleLowerCase();
    return groupRoomsByFloor(rooms)
      .filter(section => floor === "all" || section.floor === Number(floor))
      .map(section => ({
        ...section,
        rooms: section.rooms.filter(room =>
          !keyword || (room.room_name || "").toLocaleLowerCase().includes(keyword)
        )
      }))
      .filter(section => section.rooms.length > 0);
  }, [rooms, search, floor]);

  function logout() {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    navigate("/", { replace: true });
  }

  function selectCalendarDate(day) {
    const chosenDate = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), day);
    setSelectedDate(chosenDate);
    setCalendarOpen(false);
  }

  function moveCalendarMonth(offset) {
    setCalendarMonth(current => new Date(current.getFullYear(), current.getMonth() + offset, 1));
  }

  function openBooking(room) {
    setBookingRoom(room);
    setBookingDate(getLocalDateString(new Date()));
    setBookingStart("09:00");
    setBookingEnd("10:00");
    setBookingError("");
  }

  async function submitBooking(event) {
    event.preventDefault();
    if (!user?.user_id || !bookingRoom) {
      setBookingError("ไม่พบข้อมูลผู้ใช้ กรุณาเข้าสู่ระบบใหม่");
      return;
    }
    if (bookingDate < getLocalDateString(new Date())) {
      setBookingError("วันที่จองต้องไม่อยู่ในอดีต");
      return;
    }
    const startMinutes = bookingStart.split(":").reduce((total, value) => total * 60 + Number(value), 0);
    const endMinutes = bookingEnd.split(":").reduce((total, value) => total * 60 + Number(value), 0);
    if (endMinutes <= startMinutes) {
      setBookingError("เวลาสิ้นสุดต้องอยู่หลังเวลาเริ่มต้น");
      return;
    }
    if (endMinutes - startMinutes < 60) {
      setBookingError("ต้องจองอย่างน้อย 1 ชั่วโมง");
      return;
    }

    setSavingBooking(true);
    setBookingError("");
    try {
      const response = await fetch(`${API_BASE_URL}/api/bookings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: user.user_id,
          room: bookingRoom.room_name,
          date: bookingDate,
          start_time: bookingStart,
          end_time: bookingEnd,
          purpose: ""
        })
      });
      const result = await response.json();
      if (!response.ok || !result.success) {
        throw new Error(result.message || "บันทึกการจองไม่สำเร็จ");
      }
      setBookingRoom(null);
      window.alert("จองห้องสำเร็จ");
    } catch (error) {
      console.error("Unable to save booking:", error);
      setBookingError(error.message || "เชื่อมต่อระบบจองไม่ได้");
    } finally {
      setSavingBooking(false);
    }
  }

  if (!user) return <main className="homepage"><p>กำลังโหลด...</p></main>;

  const monthYear = `${THAI_MONTHS[selectedDate.getMonth()]} ${selectedDate.getFullYear() + 543}`;
  const calendarLabel = `${selectedDate.getDate()} ${monthYear}`;
  const firstWeekday = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), 1).getDay();
  const daysInMonth = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 0).getDate();
  const daysInPreviousMonth = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), 0).getDate();
  const calendarCells = [
    ...Array.from({ length: firstWeekday }, (_, index) => ({ day: daysInPreviousMonth - firstWeekday + index + 1, muted: true })),
    ...Array.from({ length: daysInMonth }, (_, index) => ({ day: index + 1, muted: false }))
  ];
  while (calendarCells.length % 7 !== 0) {
    calendarCells.push({ day: calendarCells.length - (firstWeekday + daysInMonth) + 1, muted: true });
  }

  return (
    <div className="homepage">
      <header className="topbar">
        <nav className="nav-menu">
          <span className="nav-home" title="HOME" onClick={() => navigate("/homepage")}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M3 11.5L12 4L21 11.5" stroke="#ffffff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
              <path d="M5.5 10V19.5C5.5 20.0523 5.94772 20.5 6.5 20.5H9.5C10.0523 20.5 10.5 20.0523 10.5 19.5V15C10.5 14.4477 10.9477 14 11.5 14H12.5C13.0523 14 13.5 14.4477 13.5 15V19.5C13.5 20.0523 13.9477 20.5 14.5 20.5H17.5C18.0523 20.5 18.5 20.0523 18.5 19.5V10" stroke="#ffffff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </span>
          <span onClick={() => navigate("/mybooking")}>MY BOOKING</span>
          <span onClick={() => { window.location.href = `${process.env.PUBLIC_URL}/Guide.html`; }}>GUIDE</span>
          <span onClick={() => { window.location.href = `${process.env.PUBLIC_URL}/Rule.html`; }}>RULE</span>
          <span onClick={() => { window.location.href = `${process.env.PUBLIC_URL}/review.html`; }}>REVIEW</span>
        </nav>

        <div className="nav-right">
          <button className="profile-btn" type="button" onClick={() => setProfileOpen(open => !open)}>
            <span>PROFILE</span>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="12" cy="8" r="4" stroke="#3B3736" strokeWidth="2" />
              <path d="M4 20C4 16.6863 7.13401 14 11 14H13C16.866 14 20 16.6863 20 20" stroke="#3B3736" strokeWidth="2" strokeLinecap="round" />
            </svg>
          </button>
          {profileOpen && (
            <div className="profile-popup">
              <div className="profile-card">
                <div className="profile-header">
                  <h3>PROFILE</h3>
                  <button type="button" onClick={() => setProfileOpen(false)} aria-label="ปิดโปรไฟล์">&times;</button>
                </div>
                <div className="profile-info">
                  <p><strong>Name:</strong> <span>{user.displayname_th || user.displayname_en || ""}</span></p>
                  <p><strong>Username:</strong> <span>{user.username || ""}</span></p>
                  <p><strong>Faculty:</strong> <span>{user.faculty || ""}</span></p>
                  <p><strong>Department:</strong> <span>{user.department || user.major || ""}</span></p>
                  <p><strong>Email:</strong> <span>{user.email || ""}</span></p>
                </div>
                <button type="button" className="logout-btn" onClick={logout}>LOGOUT</button>
              </div>
            </div>
          )}
        </div>
      </header>

      <section className="hero-section">
        <div className="logo-wrapper"><img src={`${process.env.PUBLIC_URL}/logo.png`} alt="Booking CSTU Room" className="hero-image-logo" /></div>
        <div className="hero-line" />
        <div className="hero-right"><h1>BOOKING<br />CSTU ROOM</h1></div>
      </section>

      <main className="main-content">
        <div className="content-wrapper">
          <h2>ตารางการจองใช้ห้อง</h2>
          <div className="filter-section">
            <div className="filter-group">
              <label htmlFor="floorFilter">ชั้น</label>
              <select id="floorFilter" value={floor} onChange={event => setFloor(event.target.value)}>
                <option value="all">ทั้งหมด</option>
                <option value="1">1</option>
                <option value="2">2</option>
                <option value="3">3</option>
              </select>
            </div>

            <div className="filter-group">
              <label htmlFor="dateFilterBtn">วันที่</label>
              <div className="datepicker-wrapper">
                <button type="button" id="dateFilterBtn" className="date-input-btn" onClick={() => setCalendarOpen(open => !open)}>
                  <span>{calendarLabel}</span>
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <rect x="3" y="5" width="18" height="16" rx="2" stroke="#3B3736" strokeWidth="2" />
                    <path d="M3 9H21" stroke="#3B3736" strokeWidth="2" />
                    <path d="M8 3V6M16 3V6" stroke="#3B3736" strokeWidth="2" strokeLinecap="round" />
                  </svg>
                </button>
                {calendarOpen && (
                  <div className="calendar-popup" onClick={event => event.stopPropagation()}>
                    <div className="calendar-header">
                      <button type="button" onClick={() => moveCalendarMonth(-1)} aria-label="เดือนก่อนหน้า">&#8249;</button>
                      <span>{THAI_MONTHS[calendarMonth.getMonth()]} {calendarMonth.getFullYear() + 543}</span>
                      <button type="button" onClick={() => moveCalendarMonth(1)} aria-label="เดือนถัดไป">&#8250;</button>
                    </div>
                    <div className="calendar-weekdays">{WEEKDAYS.map(day => <span key={day}>{day}</span>)}</div>
                    <div className="calendar-days">
                      {calendarCells.map((cell, index) => {
                        const isToday = !cell.muted && cell.day === new Date().getDate() && calendarMonth.getMonth() === new Date().getMonth() && calendarMonth.getFullYear() === new Date().getFullYear();
                        const isSelected = !cell.muted && cell.day === selectedDate.getDate() && calendarMonth.getMonth() === selectedDate.getMonth() && calendarMonth.getFullYear() === selectedDate.getFullYear();
                        return <button key={`${cell.day}-${index}`} type="button" className={`calendar-day${cell.muted ? " muted" : ""}${isToday ? " today" : ""}${isSelected ? " selected" : ""}`} disabled={cell.muted} onClick={() => selectCalendarDate(cell.day)}>{cell.day}</button>;
                      })}
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className="filter-group search-group">
              <div className="search-box">
                <svg className="search-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <circle cx="11" cy="11" r="7" stroke="#3B3736" strokeWidth="2" />
                  <path d="M20 20L16.5 16.5" stroke="#3B3736" strokeWidth="2" strokeLinecap="round" />
                </svg>
                <input type="text" id="searchInput" placeholder="ค้นหาห้อง" value={search} onChange={event => setSearch(event.target.value)} />
              </div>
            </div>
          </div>

          <div id="floorSections">
            {roomsError ? <div className="empty-room-message">{roomsError}</div> : null}
            {!roomsError && rooms.length === 0 ? <div className="empty-room-message">กำลังโหลดข้อมูลห้อง...</div> : null}
            {!roomsError && rooms.length > 0 && filteredSections.length === 0 ? <div className="empty-room-message">ไม่พบข้อมูลห้อง</div> : null}
            {filteredSections.map(section => (
              <section className="floor-container" key={section.floor}>
                <div className="floor-tab">ชั้น {section.floor}</div>
                <div className="floor-rooms">
                  {section.rooms.map(room => (
                    <article className="room-card-dark" key={room.id || room.room_code}>
                      <div className="room-image">รูปห้อง</div>
                      <div className="room-info">
                        <div className="room-header">
                          <h2>{room.room_name || "ชื่อห้อง"}</h2>
                          <span className="capacity-badge">{room.capacity_label || `ความจุ: ${room.capacity || "-"} คน`}</span>
                        </div>
                        {room.description || room.facilities ? <p className="room-desc">{room.description || room.facilities}</p> : null}
                        <div className="time-slot">
                          <div className="time-bar" />
                          <div className="time-row">{["9:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00"].map(time => <span key={time}>{time}</span>)}</div>
                        </div>
                      </div>
                      <button type="button" className="room-book-button" onClick={() => openBooking(room)}>จองห้องนี้</button>
                    </article>
                  ))}
                </div>
              </section>
            ))}
          </div>
        </div>
      </main>

      {bookingRoom && (
        <div className="room-booking-popup" role="presentation" onClick={event => { if (event.target === event.currentTarget) setBookingRoom(null); }}>
          <section className="room-booking-dialog" role="dialog" aria-modal="true" aria-labelledby="bookingPopupTitle">
            <div className="room-booking-header">
              <h2 id="bookingPopupTitle">จองห้อง <span>{bookingRoom.room_name}</span></h2>
              <button type="button" onClick={() => setBookingRoom(null)} aria-label="ปิด">&times;</button>
            </div>
            <form id="roomBookingForm" onSubmit={submitBooking}>
              <label htmlFor="roomBookingDate">วันที่</label>
              <input id="roomBookingDate" type="date" min={getLocalDateString(new Date())} value={bookingDate} onChange={event => setBookingDate(event.target.value)} required />
              <label htmlFor="roomBookingStart">เวลาเริ่ม</label>
              <input id="roomBookingStart" type="time" value={bookingStart} onChange={event => setBookingStart(event.target.value)} required />
              <label htmlFor="roomBookingEnd">เวลาสิ้นสุด</label>
              <input id="roomBookingEnd" type="time" value={bookingEnd} onChange={event => setBookingEnd(event.target.value)} required />
              {bookingError ? <p id="roomBookingError" role="alert">{bookingError}</p> : null}
              <button type="submit" id="submitRoomBooking" disabled={savingBooking}>{savingBooking ? "กำลังบันทึก..." : "ยืนยันการจอง"}</button>
            </form>
          </section>
        </div>
      )}
    </div>
  );
}

export default Homepage;
